def f(A):
    A=np.array(A); H,W=A.shape
    import collections
    def nbr(i,j): return [A[(i-1)%H][j],A[(i+1)%H][j],A[i][(j-1)%W],A[i][(j+1)%W]]
    changed=True
    while changed:
        changed=False
        for i in range(H):
            for j in range(W):
                if A[i][j]==3:
                    m=A[H-1-i][W-1-j]
                    nb=collections.Counter(nbr(i,j)).most_common(1)[0][0]
                    v=m if m!=3 else nb
                    if v!=A[i][j]:
                        A[i][j]=v; changed=True
    return [[int(x) for x in row] for row in A.tolist()]
